import { lazy, Suspense } from "react";
import BasicLayout from "../layouts/BasicLayout";
import OrderRouter from "./OrderRouter";
import BuyerRouter from "./BuyerRouter";
import PlanRouter from "./PlanRouter";
import StockRouter from "./StockRouter";

// 데모 모드에서는 로그인 검사 막기
// import ProtectedRouter from "./protected/ProtectedRouter";

const { createHashRouter } = require("react-router-dom");

const UserLogin = lazy(() => import("../pages/user/UserLogin"));
const WoodenMain = lazy(() => import("../pages/WoodenMainPage"));
const UserJoin = lazy(() => import("../pages/user/UserJoin"));
const Loading = <div>Loading...</div>;

const root = createHashRouter([
  {
    path: "",
    element: <BasicLayout />,
    children: [
      {
        path: "",
        element: (
          // 데모에서는 보호 라우트 제거
          <Suspense fallback={Loading}>
            <WoodenMain />
          </Suspense>
        ),
      },
      {
        path: "login",
        element: (
          <Suspense fallback={Loading}>
            <UserLogin />
          </Suspense>
        ),
      },
      {
        path: "join",
        element: (
          <Suspense fallback={Loading}>
            <UserJoin />
          </Suspense>
        ),
      },
      {
        path: "order",
        children: OrderRouter(),
      },
      {
        path: "buyer",
        children: BuyerRouter(),
      },
      {
        path: "plan",
        children: PlanRouter(),
      },
      {
        path: "stock",
        children: StockRouter(),
      },
    ],
  },
]);

export default root;
